// writeThresholds 把一段配置内容写进临时文件，返回路径。
func writeThresholds(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("写临时配置失败: %v", err)
	}
	return path
}

// useThresholds 把公开入口 LowStockThreshold 的配置路径临时指向 path。
func useThresholds(t *testing.T, path string) {
	t.Helper()
	old := thresholdsPath
	thresholdsPath = func() string { return path }
	t.Cleanup(func() { thresholdsPath = old })
}

func TestThresholdConfigReadConfiguredWarehouse(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"xian": 3}`))
	if got := LowStockThreshold("xian"); got != 3 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望配置的 3", got)
	}
}

func TestThresholdConfigReadUnconfiguredFallsBack(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"xian": 3}`))
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(chengdu) = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

// TestThresholdConfigReadDefaultPathIsRepoConfig 核对默认接缝（thresholdsPath
// 变量没被替换时）解析到仓库根的 config/thresholds.json；仓库根独立由 CWD 推导。
func TestThresholdConfigReadDefaultPathIsRepoConfig(t *testing.T) {
	cwd, err := os.Getwd()
	if err != nil {
		t.Fatalf("Getwd: %v", err)
	}
	want := filepath.Join(filepath.Dir(cwd), "config", "thresholds.json")
	if got := thresholdsPath(); got != want {
		t.Fatalf("thresholdsPath() = %q, 期望 %q", got, want)
	}
}

func TestThresholdConfigReadRepoConfigFallsBack(t *testing.T) {
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(chengdu) = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

func TestThresholdConfigFallbackMissingFile(t *testing.T) {
	path := filepath.Join(t.TempDir(), "does-not-exist.json")
	if got := thresholdFromFile(path, "xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置不存在时应回退默认值，得到 %d", got)
	}
}

func TestThresholdConfigFallbackUnreadableFile(t *testing.T) {
	// 目录不是可读的配置文件，os.ReadFile 会失败。
	if got := thresholdFromFile(t.TempDir(), "xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置读不出来时应回退默认值，得到 %d", got)
	}
}

func TestThresholdConfigFallbackNonObject(t *testing.T) {
	for _, content := range []string{`{`, `not json`, `[1,2,3]`, `"string"`, `123`, `null`} {
		path := writeThresholds(t, content)
		if got := thresholdFromFile(path, "xian"); got != DefaultLowStockThreshold {
			t.Fatalf("内容 %q 不是 JSON 对象时应回退默认值，得到 %d", content, got)
		}
	}
}

func TestThresholdConfigFallbackMalformedEntry(t *testing.T) {
	path := writeThresholds(t, `{"xian": 3, "chengdu": "abc"}`)
	if got := thresholdFromFile(path, "xian"); got != 3 {
		t.Fatalf("合法条目不应被同文件里的坏条目拖累，得到 %d", got)
	}
	if got := thresholdFromFile(path, "chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("坏条目应回退默认值，得到 %d", got)
	}
}

func TestThresholdConfigFallbackNullEntry(t *testing.T) {
	path := writeThresholds(t, `{"xian": null}`)
	if got := thresholdFromFile(path, "xian"); got != DefaultLowStockThreshold {
		t.Fatalf("null 条目应回退默认值，得到 %d", got)
	}
}

